// Independent PLAY-04 opening-fix re-check probe (da050d5). Actual PostgreSQL test database and actual engine worker;
// injected simulated UTC (DB sampler) with matching monotonic health time; native qualification policy values.
// A/B re-check findings 1 and 2; C re-checks R1 (opening concessions); D/E check the unleased concession commit fences.
import assert from 'node:assert/strict';
import { randomUUID, createHash } from 'node:crypto';
import * as database from './packages/db/dist/index.js';
import { createMatchService } from './apps/match-service/dist/service.js';
import { createClockHealth } from './apps/match-service/dist/clock-health.js';
import { createEngineExecutor } from './apps/match-service/dist/engine-executor.js';
import { createReleaseRegistry } from './packages/service-runtime/dist/index.js';
import { releases, using, cleanup } from './apps/match-service/tests/fixtures.mjs';

const NATIVE = { schemaVersion: 1, id: 'qualification-dynamic-v1', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0 };
const manifest = JSON.parse(JSON.stringify(releases().active)); manifest.protocol = { min: 2, max: 3 };
manifest.releaseId = 'audit-play04-open-' + createHash('sha256').update(JSON.stringify(manifest)).digest('hex').slice(0, 36);
const out = {};
let utc = 1_800_000_000_000;
const owned = [];
const jobs = [];
const delay = { transitionFor: null, transitionMs: 0 };

const repository = database.createClockRepository('test', undefined, { sampleForTest: async () => utc });
const health = createClockHealth({ monotonicNow: () => utc - 1_800_000_000_000 });
const base = createEngineExecutor();
const executor = {
  execute: async job => {
    jobs.push(job.kind + (job.command ? ':' + job.command.actor + ':' + job.command.move : ''));
    if (job.kind === 'transition' && delay.transitionMs && job.command.actor === delay.transitionFor) await new Promise(r => setTimeout(r, delay.transitionMs));
    return base.execute(job);
  },
  project: job => base.project(job), close: () => base.close(),
};
const s = createMatchService({ repository, releases: createReleaseRegistry([manifest], manifest.releaseId), executor, clocks: { repository, health, runner: { enabled: false }, recoveryAuthority: async () => null } });

const clockOf = (id, p = 'p1') => s.readClock(p, { matchId: id });
const rem = (c, p) => c.players.find(x => x.playerId === p).remainingMs;
async function wait(ms) { while (ms > 0) { const step = Math.min(ms, 10000); utc += step; ms -= step; await s.tickClocks(); } }
async function version(id) { return (await s.view('p1', { matchId: id })).stateVersion; }
function submitAt(actor, id, v, move, input = {}, commandId = randomUUID()) { return s.submit(actor, { matchId: id, commandId, expectedVersion: v, move, input }); }
async function stored(id) { return using('match', async c => (await c.query('SELECT state,reservation FROM match.clocks WHERE match_id=$1', [id])).rows[0]); }
async function eventCount(id) { return using('match', async c => (await c.query('SELECT count(*)::int AS n FROM match.clock_events WHERE match_id=$1', [id])).rows[0].n); }
async function systemReceipts(id) { return using('match', async c => (await c.query("SELECT count(*)::int AS n FROM match.command_receipts WHERE match_id=$1 AND actor_id LIKE 'system-clock%'", [id])).rows[0].n); }
const label = r => r.receipt.outcome + '/' + r.receipt.reason;

// Independent native model (same as RUN096): charge active; exhausted outgoing player resets on hand-off;
// actor earns the action bonus plus the pass bonus for passTurn; everything capped.
function model(active, A) { return { active, A, rem: { p1: 150000, p2: 150000 } }; }
function accept(m, t, actor, move, nextActive) {
  m.rem[m.active] -= t - m.A;
  if (nextActive !== m.active && m.rem[m.active] <= 0) m.rem[m.active] = 60000;
  m.rem[actor] = Math.min(150000, m.rem[actor] + 5000 + (move === 'passTurn' ? 60000 : 0));
  m.active = nextActive; m.A = t;
}
async function expectClock(id, m, what) {
  const c = await clockOf(id);
  assert.equal(c.status, 'running', what + ' status'); assert.equal(c.activePlayerId, m.active, what + ' active');
  for (const p of ['p1', 'p2']) assert.equal(rem(c, p), Math.max(0, m.rem[p] - (p === m.active ? utc - m.A : 0)), what + ' remaining ' + p);
  assert.equal(c.deadlineMs, m.A + Math.max(0, m.rem[m.active]), what + ' deadline');
  const st = (await stored(id)).state; assert.deepEqual(st.remainingMs, m.rem, what + ' stored remaining'); assert.equal(st.anchorUtcMs, m.A, what + ' anchor');
  return c;
}
async function openMatch(id) {
  await s.create({ matchId: id, players: ['p1', 'p2'], clock: NATIVE });
  const chooser = (await s.view('p1', { matchId: id })).priorityId, m = model(chooser, utc);
  let r = await submitAt(chooser, id, 0, 'chooseWhoGoesFirst', { playerId: 'p1' }); assert.equal(r.receipt.outcome, 'accepted');
  accept(m, utc, chooser, 'chooseWhoGoesFirst', (await clockOf(id)).activePlayerId);
  for (let i = 0; i < 2; i++) {
    await wait(2000); const a = (await clockOf(id)).activePlayerId;
    r = await submitAt(a, id, await version(id), 'alterHand', { cardsToMulligan: [] }); assert.equal(r.receipt.outcome, 'accepted');
    accept(m, utc, a, 'alterHand', (await clockOf(id)).activePlayerId);
  }
  await expectClock(id, m, 'opened ' + id); return m;
}

try {
  // ---------- A. finding 1: waiting non-concession commands never reserve, charge or delay the active player ----------
  const idA = 'audit-p04open-' + randomUUID(); owned.push(idA);
  const m = await openMatch(idA);
  await wait(3000);
  const other = p => (p === 'p1' ? 'p2' : 'p1');
  const before = await clockOf(idA), eventsBefore = await eventCount(idA), jobsBefore = jobs.length;
  let r = await submitAt(other(m.active), idA, before.stateVersion, 'passTurn');
  out.A_waitingRefusal = { receipt: label(r), engineJobs: jobs.slice(jobsBefore), clockRevisionDelta: (await clockOf(idA)).clockRevision - before.clockRevision, clockEventsDelta: (await eventCount(idA)) - eventsBefore };
  assert.equal(r.receipt.outcome, 'rejected'); assert.equal(r.receipt.reason, 'invalid_intent');
  assert.deepEqual(out.A_waitingRefusal.engineJobs, []); assert.equal(out.A_waitingRefusal.clockRevisionDelta, 0); assert.equal(out.A_waitingRefusal.clockEventsDelta, 0);
  await expectClock(idA, m, 'after waiting refusal');
  // the original RUN096 reproduction: waiting command in flight while the active player moves
  const tally = { activeAccepted: 0, activeOther: [], waiting: {} };
  for (let turn = 0; turn < 8; turn++) {
    await wait(2000);
    const v = await version(idA), active = m.active, waiting = other(active);
    const spam = [0, 1, 2].map(() => submitAt(waiting, idA, v, turn % 2 ? 'passTurn' : 'alterHand', turn % 2 ? {} : { cardsToMulligan: [] }).then(label, e => 'threw ' + e.code));
    const genuine = submitAt(active, idA, v, 'passTurn').then(label, e => 'threw ' + e.code);
    const [g, ...w] = await Promise.all([genuine, ...spam]);
    if (g === 'accepted/null') { tally.activeAccepted++; accept(m, utc, active, 'passTurn', waiting); } else tally.activeOther.push(g);
    for (const x of w) tally.waiting[x] = (tally.waiting[x] ?? 0) + 1;
    await expectClock(idA, m, 'turn ' + turn);
  }
  out.A_concurrentTurns = tally;
  assert.equal(tally.activeAccepted, 8); assert.equal(Object.keys(tally.waiting).every(k => k === 'rejected/invalid_intent' || k === 'stale/stale_state'), true);

  // ---------- B. finding 2: waiting concession across the active deadline; active player's own command still expires ----------
  const c0 = await clockOf(idA); const activeB = m.active, waitingB = other(activeB);
  await wait(c0.deadlineMs - 1 - utc - ((c0.deadlineMs - 1 - utc) % 10000)); utc = c0.deadlineMs - 1; await s.tickClocks();
  assert.equal(rem(await clockOf(idA), activeB), 1);
  utc += 1; const vB = await version(idA), revB = (await clockOf(idA)).clockRevision;
  out.B_atExactDeadline = {};
  r = await submitAt(waitingB, idA, vB, 'passTurn'); out.B_atExactDeadline.waitingNonConcession = label(r);
  assert.equal(r.receipt.reason, 'invalid_intent'); assert.equal((await clockOf(idA)).clockRevision, revB);
  r = await submitAt(activeB, idA, vB, 'concede'); out.B_atExactDeadline.activeOwnConcession = label(r);
  const concedeId = randomUUID(); r = await submitAt(waitingB, idA, vB, 'concede', {}, concedeId); out.B_atExactDeadline.waitingConcession = label(r);
  assert.equal(r.receipt.outcome, 'accepted');
  await Promise.all([s.tickClocks(), s.tickClocks()]);
  const endV = await s.view('p1', { matchId: idA }), dup = await submitAt(waitingB, idA, vB, 'concede', {}, concedeId), stB = (await stored(idA)).state;
  out.B_atExactDeadline.after = { ended: endV.ended ?? endV.winner !== null, winner: endV.winner, expectedWinner: activeB, systemTimeoutReceipts: await systemReceipts(idA), duplicateSameReceipt: dup.duplicate && JSON.stringify(dup.receipt) === JSON.stringify(r.receipt), clockStatus: stB.status, storedRemaining: stB.remainingMs };
  assert.equal(endV.winner, activeB); assert.equal(out.B_atExactDeadline.after.systemTimeoutReceipts, 0); assert.equal(out.B_atExactDeadline.after.duplicateSameReceipt, true); assert.equal(stB.status, 'ended');
  // past the deadline (sweep not yet run): 3 s late
  const idB = 'audit-p04open-' + randomUUID(); owned.push(idB);
  const mB = await openMatch(idB); const cB = await clockOf(idB);
  const tB = cB.deadlineMs - 1; await wait(tB - utc - ((tB - utc) % 10000)); const vLate = await version(idB); utc = cB.deadlineMs + 3000;
  r = await submitAt(other(mB.active), idB, vLate, 'concede'); const endB = await s.view('p1', { matchId: idB });
  out.B_threeSecondsLate = { waitingConcession: label(r), versionBefore: vLate, receiptVersion: r.receipt.stateVersion, winner: endB.winner, expectedWinner: mB.active, systemTimeoutReceipts: await systemReceipts(idB), clockStatus: (await stored(idB)).state.status };
  assert.equal(r.receipt.outcome, 'accepted'); assert.equal(endB.winner, mB.active); assert.equal(out.B_threeSecondsLate.systemTimeoutReceipts, 0);

  // ---------- C. R1: opening concessions are refused without taking or revising the clock, and never block the active player ----------
  const idC = 'audit-p04open-' + randomUUID(); owned.push(idC);
  await s.create({ matchId: idC, players: ['p1', 'p2'], clock: NATIVE });
  const chooser = (await s.view('p1', { matchId: idC })).priorityId, waitingC = other(chooser);
  await s.view(waitingC, { matchId: idC }); await clockOf(idC);
  const times = []; let revDelta = 0, evDelta = 0; const reasons = {};
  for (let i = 0; i < 20; i++) {
    const rev = (await clockOf(idC)).clockRevision, ev = await eventCount(idC), t0 = performance.now();
    r = await submitAt(waitingC, idC, 0, 'concede'); times.push(performance.now() - t0);
    reasons[label(r)] = (reasons[label(r)] ?? 0) + 1; revDelta += (await clockOf(idC)).clockRevision - rev; evDelta += (await eventCount(idC)) - ev;
  }
  times.sort((a, b) => a - b);
  out.C_openingConcessions = { count: 20, receipts: reasons, clockRevisionDelta: revDelta, clockEventsDelta: evDelta, versionAfter: await version(idC), submitMs: { min: +times[0].toFixed(1), median: +times[10].toFixed(1), max: +times[19].toFixed(1) } };
  assert.deepEqual(reasons, { 'rejected/invalid_intent': 20 }); assert.equal(revDelta, 0); assert.equal(evDelta, 0);
  delay.transitionFor = waitingC; delay.transitionMs = 300;
  const choiceId = randomUUID(), revBefore = (await clockOf(idC)).clockRevision;
  const held = submitAt(waitingC, idC, 0, 'concede').then(label, e => 'threw ' + e.code);
  await new Promise(res => setTimeout(res, 100));
  const during = await stored(idC);
  const t1 = performance.now(), genuine = await submitAt(chooser, idC, 0, 'chooseWhoGoesFirst', { playerId: 'p1' }, choiceId).then(label, e => 'threw ' + e.code), genuineMs = performance.now() - t1;
  const heldResult = await held; delay.transitionMs = 0;
  out.C_overlap = { clockStatusWhileWaitingConcessionRuns: during.state.status, reservationWhileWaitingConcessionRuns: during.reservation, revisionUnchangedDuring: during.state.revision === revBefore, chooserGenuineChoice: genuine, chooserMs: +genuineMs.toFixed(1), waitingConcession: heldResult };
  assert.equal(during.state.status, 'running'); assert.equal(during.reservation, null); assert.equal(genuine, 'accepted/null'); assert.equal(heldResult, 'stale/stale_state');
  const a1 = (await clockOf(idC)).activePlayerId, rev1 = (await clockOf(idC)).clockRevision, ev1 = await eventCount(idC);
  r = await submitAt(other(a1), idC, 1, 'concede');
  out.C_mulliganWaitingConcession = { receipt: label(r), clockRevisionDelta: (await clockOf(idC)).clockRevision - rev1, clockEventsDelta: (await eventCount(idC)) - ev1 };
  assert.equal(r.receipt.reason, 'invalid_intent'); assert.equal(out.C_mulliganWaitingConcession.clockRevisionDelta, 0);

  // ---------- D. main game: a heartbeat during the unleased evaluation does not make the concession stale ----------
  const idD = 'audit-p04open-' + randomUUID(); owned.push(idD);
  const mD = await openMatch(idD); const vD = await version(idD), waitingD = other(mD.active);
  delay.transitionFor = waitingD; delay.transitionMs = 400;
  const concD = submitAt(waitingD, idD, vD, 'concede').then(label, e => 'threw ' + e.code);
  await new Promise(res => setTimeout(res, 100));
  const hbBefore = (await stored(idD)).state; utc += 1000; await s.tickClocks(); const hbAfter = (await stored(idD)).state;
  const resD = await concD; delay.transitionMs = 0; const endD = await s.view('p1', { matchId: idD }), stD = (await stored(idD)).state;
  out.D_heartbeatDuringEvaluation = { heartbeatAdvanced: hbAfter.lastHealthyUtcMs > hbBefore.lastHealthyUtcMs, revisionUnchangedByHeartbeat: hbAfter.revision === hbBefore.revision, concession: resD, winner: endD.winner, expectedWinner: mD.active, clockStatus: stD.status, storedRemaining: stD.remainingMs };
  assert.equal(out.D_heartbeatDuringEvaluation.heartbeatAdvanced, true); assert.equal(resD, 'accepted/null'); assert.equal(endD.winner, mD.active); assert.equal(stD.status, 'ended');

  // ---------- E. a timeout committed during the unleased evaluation makes the concession stale; a fresh concession then works ----------
  const idE = 'audit-p04open-' + randomUUID(); owned.push(idE);
  const mE = await openMatch(idE); const cE = await clockOf(idE), activeE = mE.active, waitingE = other(activeE);
  const tE = cE.deadlineMs - 1; await wait(tE - utc - ((tE - utc) % 10000)); utc = cE.deadlineMs; const vE = await version(idE);
  delay.transitionFor = waitingE; delay.transitionMs = 400;
  const concE = submitAt(waitingE, idE, vE, 'concede').then(label, e => 'threw ' + e.code);
  await new Promise(res => setTimeout(res, 100));
  await s.tickClocks(); const afterTimeout = await s.view('p1', { matchId: idE });
  const resE = await concE; delay.transitionMs = 0;
  r = await submitAt(waitingE, idE, await version(idE), 'concede'); const endE = await s.view('p1', { matchId: idE });
  out.E_timeoutDuringEvaluation = { versionBefore: vE, versionAfterTimeout: afterTimeout.stateVersion, turnOwnerAfterTimeout: afterTimeout.turnOwnerId, concessionDuringTimeout: resE, systemTimeoutReceipts: await systemReceipts(idE), freshConcessionAsActive: label(r), winner: endE.winner, expectedWinner: activeE };
  assert.equal(afterTimeout.stateVersion, vE + 1); assert.equal(resE, 'stale/stale_state'); assert.equal(out.E_timeoutDuringEvaluation.systemTimeoutReceipts, 1); assert.equal(r.receipt.outcome, 'accepted'); assert.equal(endE.winner, activeE);
} catch (error) { out.error = String(error && error.stack || error); } finally {
  await s.close();
  for (const id of owned) await cleanup(id).catch(() => {});
}
console.log(JSON.stringify(out, null, 1));
